//! In-crate tests for the founding pipeline.
//!
//! The `*_matches_js_reference` pins were generated by running the VERBATIM
//! TypeScript algorithms (`F:\MB\src\core\rng.ts`, `noise.ts`, castgen's
//! `hslToHex`) under node and copying the printed f64s — they prove the Rust
//! port is bit-identical to the JS semantics, not merely self-consistent.

use crate::castgen::{assert_cast, hsl_to_hex, FreelancerWant};
use crate::founding::{new_founding, Founding};
use crate::noise::{fbm, feature_roll, hash, id_seed, value_noise};
use crate::rng::{rng_float, rng_int, RngState};
use crate::scenario::{scenario_spec, stack_max, ScenarioId, ALL_SCENARIOS};
use crate::worldgen::LandmarkKind;

fn found(seed: u32, scenario: ScenarioId) -> Founding {
    new_founding(seed, 0, scenario)
        .unwrap_or_else(|e| panic!("founding failed for seed {seed}: {e}"))
}

// ---------- Cross-language pins ----------

#[test]
fn rng_matches_js_reference() {
    // node: rngFloat stream for seed=1, counter=0 (first 8 draws).
    let expected = [
        0.18967728852294385,
        0.6980675361119211,
        0.35104472003877163,
        0.5408834095578641,
        0.4216229144949466,
        0.7368763901758939,
        0.8629396900068969,
        0.007116369437426329,
    ];
    let mut r = RngState::new(1);
    for e in expected {
        assert_eq!(rng_float(&mut r), e);
    }
    assert_eq!(r.rng_counter, 8);

    // Mid-stream resume: seed=0xdeadbeef, counter already at 1000.
    let expected2 = [
        0.6289423045236617,
        0.7224674096796662,
        0.51245949533768,
        0.6269794898107648,
    ];
    let mut r2 = RngState { seed: 0xdead_beef, rng_counter: 1000 };
    for e in expected2 {
        assert_eq!(rng_float(&mut r2), e);
    }

    // rngInt sequence for seed=42 (the founding's own opening draw shapes).
    let mut r3 = RngState::new(42);
    assert_eq!(rng_int(&mut r3, 4, 5), 4);
    assert_eq!(rng_int(&mut r3, 3, 4), 4);
    assert_eq!(rng_int(&mut r3, 2, 3), 2);
    assert_eq!(rng_int(&mut r3, 0, 5), 2);
    assert_eq!(rng_int(&mut r3, 6, 10) * 25, 200);
}

#[test]
fn noise_matches_js_reference() {
    assert_eq!(hash(1.0, 11.0), 0.9402426858293458);
    assert_eq!(hash(3_735_928_559.0, 23.0), 0.7711961361978195); // 0xdeadbeef
    assert_eq!(hash(-3.0, 7.0), 0.031008727622918952);
    assert_eq!(hash(123_456.0, -42.0), 0.5568198239330249);
    assert_eq!(id_seed("sigrun"), 1_015_095_009);
    assert_eq!(feature_roll(id_seed("sigrun"), 5), 0.5249907482706454);
    assert_eq!(id_seed("a"), 314);
    assert_eq!(feature_roll(12_345, 8), 0.3183486518259972);
    assert_eq!(fbm(10.37, -4.2, 4), 0.42905810627722535);
    assert_eq!(fbm(1234.5, 987.25, 4), 0.5125745354443574);
    assert_eq!(value_noise(0.5, 0.5), 0.48506254731562515);
}

#[test]
fn hsl_matches_js_reference() {
    assert_eq!(hsl_to_hex(0.0, 0.3, 0.34), 7_421_245);
    assert_eq!(hsl_to_hex(123.4, 0.35, 0.42), 4_624_714);
    assert_eq!(hsl_to_hex(-30.0, 0.28, 0.5), 10_706_048);
    assert_eq!(hsl_to_hex(359.9, 0.42, 0.35), 8_336_436);
}

// ---------- Determinism ----------

#[test]
fn same_seed_same_founding() {
    for seed in [1u32, 42, 777, 20_260_721] {
        let a = found(seed, ScenarioId::Village);
        let b = found(seed, ScenarioId::Village);
        assert_eq!(a, b, "seed {seed} produced two different foundings");
    }
}

#[test]
fn rng_stream_resumes_from_persisted_state() {
    let mut r = RngState::new(99);
    for _ in 0..5 {
        rng_float(&mut r);
    }
    let snapshot = serde_json::to_string(&r).unwrap();
    let ahead: Vec<f64> = (0..5).map(|_| rng_float(&mut r)).collect();
    let mut restored: RngState = serde_json::from_str(&snapshot).unwrap();
    let resumed: Vec<f64> = (0..5).map(|_| rng_float(&mut restored)).collect();
    assert_eq!(ahead, resumed);
}

#[test]
fn founding_serde_roundtrip() {
    let f = found(4242, ScenarioId::City);
    let json = serde_json::to_string(&f).unwrap();
    let back: Founding = serde_json::from_str(&json).unwrap();
    assert_eq!(f, back);
    // And the resumed rng continues the same stream on both.
    let mut a = f.resume_rng();
    let mut b = back.resume_rng();
    assert_eq!(rng_float(&mut a), rng_float(&mut b));
}

// ---------- Constraint asserts across many seeds ----------

#[test]
fn constraints_hold_across_200_seeds() {
    for i in 0..200u32 {
        let seed = i.wrapping_mul(2_654_435_761).wrapping_add(97);
        let f = found(seed, ScenarioId::Village);

        // The generation-time asserts already ran inside roll_cast; re-run
        // them against the finished founding for good measure.
        assert_cast(&f.cast).unwrap_or_else(|e| panic!("seed {seed}: {e}"));

        // Cast shape.
        let n_bands = f.cast.bands.len();
        assert!((4..=5).contains(&n_bands), "seed {seed}: {n_bands} bands");
        let freelancers = f.cast.companions.iter().filter(|c| c.band.is_none()).count();
        assert!((2..=3).contains(&freelancers), "seed {seed}: {freelancers} freelancers");

        // Roster = the founders band, 3-4 strong.
        assert!((3..=4).contains(&f.roster.len()), "seed {seed}: roster {}", f.roster.len());
        let founders_band = f.cast.bands.iter().find(|b| b.founders).unwrap();
        for id in &f.roster {
            let c = f.cast.companions.iter().find(|c| &c.id == id).unwrap();
            assert_eq!(c.band.as_deref(), Some(founders_band.id.as_str()));
        }

        // Founder perk guarantees: at least one of tracker/trader/surgeon
        // aboard, and at least two founder perks total.
        let founder_perks: Vec<_> = f
            .cast
            .companions
            .iter()
            .filter(|c| c.band.as_deref() == Some(founders_band.id.as_str()))
            .filter_map(|c| c.perk)
            .collect();
        assert!(founder_perks.len() >= 2, "seed {seed}: founder perks {founder_perks:?}");
        use crate::castgen::PerkId;
        assert!(
            founder_perks
                .iter()
                .any(|p| matches!(p, PerkId::Tracker | PerkId::Trader | PerkId::Surgeon)),
            "seed {seed}: no utility perk among founders"
        );

        // World shape: 13 slots, near-all placed, EXACTLY one city.
        let n_lm = f.world.landmarks.len();
        assert!(n_lm >= 10, "seed {seed}: only {n_lm} landmarks");
        let cities = f.world.landmarks.iter().filter(|l| l.kind == LandmarkKind::City).count();
        assert_eq!(cities, 1, "seed {seed}: {cities} cities");

        // Homes bind to real landmarks, keys are cast members or bands.
        for (key, lm) in &f.world.homes {
            assert!(f.world.landmark_by_id(lm).is_some(), "seed {seed}: home '{key}' -> missing '{lm}'");
            let ok = if let Some(band_id) = key.strip_prefix("band:") {
                f.cast.bands.iter().any(|b| b.id == band_id)
            } else {
                f.cast.companions.iter().any(|c| &c.id == key)
            };
            assert!(ok, "seed {seed}: home key '{key}' unknown");
        }

        // Band states: one per band, camps are real landmarks, founders
        // signed with patience 100.
        assert_eq!(f.band_states.len(), f.cast.bands.len());
        for (band_id, st) in &f.band_states {
            assert!(f.world.landmark_by_id(&st.camp_landmark_id).is_some(), "seed {seed}: band '{band_id}' camps nowhere");
        }
        let founders_state = &f
            .band_states
            .iter()
            .find(|(id, _)| *id == founders_band.id)
            .unwrap()
            .1;
        assert_eq!(founders_state.patience, 100);
        assert_eq!(founders_state.status, crate::worldgen::BandStatus::Signed);

        // Freelancer wants reference real things.
        for c in f.cast.companions.iter().filter(|c| c.band.is_none()) {
            match &c.want {
                Some(FreelancerWant::Band { band_id }) => {
                    assert!(f.cast.bands.iter().any(|b| !b.founders && &b.id == band_id));
                }
                Some(_) => {}
                None => panic!("seed {seed}: freelancer '{}' has no want", c.id),
            }
        }
    }
}

// ---------- The comparability law ----------

#[test]
fn comparability_law_across_all_four_scenarios() {
    let seed = 777u32;
    let village = found(seed, ScenarioId::Village);
    let town = found(seed, ScenarioId::Town);
    let wild = found(seed, ScenarioId::Wilderness);
    let city = found(seed, ScenarioId::City);

    for other in [&town, &wild, &city] {
        // Everything ROLLED is identical…
        assert_eq!(village.name, other.name);
        assert_eq!(village.cast, other.cast);
        assert_eq!(village.world, other.world);
        assert_eq!(village.band_states, other.band_states);
        assert_eq!(village.colony_terrain, other.colony_terrain);
        assert_eq!(village.roster, other.roster);
        // …including the stream position: the scenario took zero draws.
        assert_eq!(village.rng_counter, other.rng_counter);
    }

    // What the scenario stamps differs, verbatim from the spec table.
    assert_eq!(village.gold, 90);
    assert_eq!(town.gold, 420);
    assert_eq!(wild.gold, 25);
    assert_eq!(city.gold, 200);
    assert_eq!(village.standing, 10);
    assert_eq!(town.standing, -30);
    assert_eq!(wild.standing, 0);
    assert_eq!(city.standing, 0);
    assert_eq!(village.provisioning, 4);
    assert_eq!(wild.provisioning, 0, "no market in the wild — no provisioner");
    assert_eq!(city.provisioning, 4);

    // The resource cache lands at the cache ground, in spec order.
    assert_eq!(
        village.stacks.iter().map(|s| (s.item.as_str(), s.count)).collect::<Vec<_>>(),
        vec![("meal", 14), ("timber", 10), ("plank", 4)]
    );
    assert_eq!(
        town.stacks.iter().map(|s| (s.item.as_str(), s.count)).collect::<Vec<_>>(),
        vec![("meal", 26), ("timber", 18), ("plank", 12), ("herbs", 6)]
    );
    for s in &village.stacks {
        assert_eq!((s.q, s.r), (0, 0));
    }
    // Spoil stamped as absolute day at drop (day 1 + meal's 3).
    assert_eq!(village.stacks[0].spoil_day, Some(4));
    assert_eq!(village.stacks[1].spoil_day, None); // timber keeps
}

// ---------- Name-constraint torture ----------

#[test]
fn name_constraint_torture() {
    const RESERVED: [&str; 7] = [
        "looter", "bandit", "raider", "warlord", "elite_leader", "hero", "founding",
    ];
    const BANNED: [&str; 2] = ["alien", "marys"];
    for i in 0..200u32 {
        let seed = i.wrapping_mul(40_503).wrapping_add(1_299_721);
        let f = found(seed, ScenarioId::Town);
        // The shared taken pool: companion names AND band fore-names (a
        // companion name inside a band name would linkify mid-word).
        let mut pool: Vec<String> = f.cast.companions.iter().map(|c| c.name.to_lowercase()).collect();
        pool.extend(f.cast.bands.iter().map(|b| b.id.clone())); // fore, lowercased
        for (i, a) in pool.iter().enumerate() {
            assert!(!RESERVED.contains(&a.as_str()), "seed {seed}: reserved name '{a}'");
            assert!(!BANNED.contains(&a.as_str()), "seed {seed}: banned name '{a}'");
            for b in pool.iter().skip(i + 1) {
                let p4a = &a[..a.len().min(4)];
                let p4b = &b[..b.len().min(4)];
                assert_ne!(p4a, p4b, "seed {seed}: '{a}'/'{b}' share a 4-char prefix");
                assert!(
                    !a.contains(b.as_str()) && !b.contains(a.as_str()),
                    "seed {seed}: '{a}'/'{b}' nest"
                );
            }
        }
        // Ids: lowercase-safe charset, globally unique (companions + bands).
        let mut ids: Vec<&str> = f.cast.companions.iter().map(|c| c.id.as_str()).collect();
        ids.extend(f.cast.bands.iter().map(|b| b.id.as_str()));
        for id in &ids {
            assert!(
                id.chars().next().is_some_and(|c| c.is_ascii_lowercase())
                    && id.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'),
                "seed {seed}: unsafe id '{id}'"
            );
        }
        let n = ids.len();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), n, "seed {seed}: duplicate id");
    }
}

// ---------- Scenario data sanity (the TS module-load validation) ----------

#[test]
fn scenario_tables_are_sane() {
    for id in ALL_SCENARIOS {
        let s = scenario_spec(id);
        assert_eq!(s.id, id, "scenario id mismatch");
        assert!(!s.name.is_empty() && !s.blurb.is_empty(), "scenario needs prose");
        assert!(s.gold >= 0 && s.trade_per_day >= 0 && s.meal_price >= 0 && s.rent_per_day >= 0);
        // The simplified cache drop (one fresh stack per item) is only valid
        // while every stock count fits its stackMax — assert it.
        for &(item, n) in s.stock {
            assert!(n <= stack_max(item), "stock {item} x{n} exceeds stackMax");
        }
    }
    // The identity table, verbatim.
    assert!(scenario_spec(ScenarioId::Village).recruiting);
    assert!(!scenario_spec(ScenarioId::Town).recruiting);
    assert!(!scenario_spec(ScenarioId::Wilderness).recruiting);
    assert!(scenario_spec(ScenarioId::City).recruiting);
    assert_eq!(scenario_spec(ScenarioId::Village).sign_discount, 0.55);
    assert_eq!(scenario_spec(ScenarioId::City).sign_discount, 0.8);
    assert_eq!(scenario_spec(ScenarioId::City).rent_per_day, 8);
    assert_eq!(scenario_spec(ScenarioId::Wilderness).meal_price, 0);
    assert_eq!(scenario_spec(ScenarioId::Town).trade_per_day, 14);
}
